import{_ as a,o as i,c as t,a3 as e}from"./chunks/framework.BTt0kA_k.js";const c=JSON.parse('{"title":"开发环境与源码运行","description":"","frontmatter":{},"headers":[],"relativePath":"developer/getting-started.md","filePath":"developer/getting-started.md"}'),n={name:"developer/getting-started.md"};function l(p,s,h,d,r,o){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="开发环境与源码运行" tabindex="-1">开发环境与源码运行 <a class="header-anchor" href="#开发环境与源码运行" aria-label="Permalink to &quot;开发环境与源码运行&quot;">​</a></h1><h2 id="准备工具" tabindex="-1">准备工具 <a class="header-anchor" href="#准备工具" aria-label="Permalink to &quot;准备工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>项目要求</th></tr></thead><tbody><tr><td>Git</td><td>获取仓库和维护变更</td></tr><tr><td>Node.js</td><td>22.12 或以上版本</td></tr><tr><td>pnpm</td><td>9.10.0，与根 <code>package.json</code> 的 <code>packageManager</code> 一致</td></tr><tr><td>Rust</td><td>stable 工具链，包含 Cargo</td></tr><tr><td>macOS 编译依赖</td><td>Xcode 或 Xcode Command Line Tools</td></tr></tbody></table><p>仅开发 macOS 桌面应用时，可使用 Command Line Tools。安装方式见 <a href="https://v2.tauri.app/start/prerequisites/#macos" target="_blank" rel="noreferrer">Tauri 官方前置依赖说明</a>。</p><p>安装后可检查工具是否可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xcode-select</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span></span></code></pre></div><h2 id="获取代码并启动桌面端" tabindex="-1">获取代码并启动桌面端 <a class="header-anchor" href="#获取代码并启动桌面端" aria-label="Permalink to &quot;获取代码并启动桌面端&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/skyzfdance/RelayPulse.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RelayPulse</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:desktop</span></span></code></pre></div><p>命令启动 <strong>RelayPulse Dev</strong>，同时运行 Vue 前端和真实 Rust 后端。首次启动会下载并编译依赖，耗时取决于网络与机器性能。</p><p>出现主窗口后，使用测试站点完成一次探测，确认前端与后端连通。系统托盘、小面板位置、原生材质、通知权限和真实模型请求均需在桌面端验证。</p><h2 id="只开发前端页面" tabindex="-1">只开发前端页面 <a class="header-anchor" href="#只开发前端页面" aria-label="Permalink to &quot;只开发前端页面&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:web</span></span></code></pre></div><p>主窗口地址为 <code>http://localhost:1421</code>，小面板为 <code>http://localhost:1421/panel</code>。浏览器中的 API 由 <code>frontend/src/mocks/</code> 处理，适合检查页面、交互和模拟状态；这些结果不代表真实后端调用通过。</p><p>前端服务使用固定端口 1421。桌面启动会管理其前端服务，切换运行方式前先停止已有服务，避免占用端口。</p><h2 id="启动失败时" tabindex="-1">启动失败时 <a class="header-anchor" href="#启动失败时" aria-label="Permalink to &quot;启动失败时&quot;">​</a></h2><ol><li>先核对工具版本和终端错误，确认依赖安装成功。</li><li>前端端口被占用时，检查是否还有上一次启动的进程。</li><li>Rust 编译失败时，保留完整错误，核对 macOS 编译依赖。</li><li>运行 <code>pnpm info:desktop</code> 获取 Tauri 与系统环境信息。</li></ol><p>开发版与正式版使用各自的数据目录和系统权限，具体见<a href="./build-and-environments.html">构建与环境隔离</a>。</p><p>全部根脚本、前端子项目命令、测试过滤、Tauri 参数和文档站命令见<a href="./commands.html">开发命令参考</a>。</p>`,18)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
